"""
Camblish Alumni Hub V1.0 (desktop)
Author: Eddie Bila

Windows desktop app for the Camblish Alumni Hub. It opens the same live system as the web link in its
own window, and adds silent name-tag printing to label printers and sending login emails through Outlook.
"""
import base64
import io
import json
import os
import sys
import urllib.parse

import webview
from PIL import Image, ImageDraw, ImageFont

try:
    import win32print
    import win32ui
    from PIL import ImageWin
    HAS_WIN32 = True
except Exception:
    HAS_WIN32 = False

APP_TITLE = "Camblish Alumni Hub V1.0"
HUB_URL = "https://psychic-saint.github.io/CamblishGradHub2026/"
CREST_B64 = ""
TAG_SIZES = {"62x29": (62, 29), "50x30": (50, 30), "40x30": (40, 30), "58x40": (58, 40), "90x55": (90, 55)}


def resource(name):
    base = getattr(sys, "_MEIPASS", os.path.dirname(os.path.abspath(__file__)))
    return os.path.join(base, name)


def font(size_px, bold=False):
    names = (["segoeuib.ttf", "arialbd.ttf", "DejaVuSans-Bold.ttf"] if bold
             else ["segoeui.ttf", "arial.ttf", "DejaVuSans.ttf"])
    for n in names:
        for base in ("C:\\Windows\\Fonts", "/usr/share/fonts/truetype/dejavu", ""):
            try:
                return ImageFont.truetype(os.path.join(base, n) if base else n, size_px)
            except Exception:
                continue
    return ImageFont.load_default()


def fit_font(draw, text, max_w, start_px, bold=True, min_px=10):
    px = start_px
    while px > min_px:
        f = font(px, bold)
        if draw.textlength(text, font=f) <= max_w:
            return f
        px -= 2
    return font(min_px, bold)


def render_tag(learner, code, event_name, size_mm, dpi=300):
    w_mm, h_mm = size_mm
    W, H = int(w_mm / 25.4 * dpi), int(h_mm / 25.4 * dpi)
    mm = dpi / 25.4
    img = Image.new("RGB", (W, H), "white")
    d = ImageDraw.Draw(img)
    pad = int(2.5 * mm)
    # header: crest + event
    crest = Image.open(io.BytesIO(base64.b64decode(CREST_B64))).convert("RGB")
    ch = int(min(6, h_mm * 0.2) * mm)
    crest.thumbnail((ch, ch))
    img.paste(crest, (pad, int(1.5 * mm)))
    hf = font(int(min(2.6, h_mm * 0.09) * mm), True)
    d.text((pad + crest.width + int(1.5 * mm), int(1.5 * mm) + (crest.height - hf.size) // 2 - 2), event_name, font=hf, fill="black")
    # name
    name = learner.get("name") or " ".join(x for x in [learner.get("first_name"), learner.get("surname")] if x)
    top = int(1.5 * mm) + crest.height + int(1.2 * mm)
    nf = fit_font(d, name, W - 2 * pad, int(h_mm * 0.24 * mm))
    d.text((pad, top), name, font=nf, fill="black")
    # bottom row: programme + code box
    cf = font(int(h_mm * 0.22 * mm), True)
    cw = d.textlength(code, font=cf)
    box_w, box_h = int(cw + 3 * mm), int(cf.size * 1.25)
    bx, by = W - pad - box_w, H - int(1.5 * mm) - box_h
    d.rounded_rectangle([bx, by, bx + box_w, by + box_h], radius=int(1.5 * mm), outline="black", width=max(3, int(0.5 * mm)))
    d.text((bx + (box_w - cw) / 2, by + (box_h - cf.size) / 2 - cf.size * 0.12), code, font=cf, fill="black")
    prog = learner.get("programme") or ""
    if learner.get("nqf"):
        prog += f"  ·  NQF {learner['nqf']}"
    pf = fit_font(d, prog, bx - pad - int(2 * mm), int(h_mm * 0.1 * mm), bold=False, min_px=8)
    d.text((pad, by + (box_h - pf.size) / 2), prog, font=pf, fill="black")
    return img


def list_printers():
    if not HAS_WIN32:
        return []
    flags = win32print.PRINTER_ENUM_LOCAL | win32print.PRINTER_ENUM_CONNECTIONS
    return [p[2] for p in win32print.EnumPrinters(flags)]


def print_image(img, printer):
    """Prints straight to the printer, scaled to its printable area. No dialog."""
    if not HAS_WIN32:
        raise RuntimeError("Printing needs Windows.")
    printer = printer or win32print.GetDefaultPrinter()
    hdc = win32ui.CreateDC()
    hdc.CreatePrinterDC(printer)
    pw, ph = hdc.GetDeviceCaps(8), hdc.GetDeviceCaps(10)   # HORZRES, VERTRES
    iw, ih = img.size
    # rotate if the driver's page is portrait and the label is landscape
    if (pw < ph) != (iw < ih):
        img = img.rotate(90, expand=True)
        iw, ih = img.size
    scale = min(pw / iw, ph / ih)
    w, h = int(iw * scale), int(ih * scale)
    x, y = (pw - w) // 2, (ph - h) // 2
    hdc.StartDoc("Graduation name tag")
    hdc.StartPage()
    ImageWin.Dib(img).draw(hdc.GetHandleOutput(), (x, y, x + w, y + h))
    hdc.EndPage()
    hdc.EndDoc()
    hdc.DeleteDC()


class Bridge:
    """Functions the hub page can call through window.pywebview.api"""

    def list_printers(self):
        try:
            return list_printers()
        except Exception:
            return []

    def print_tags(self, items, size_key="62x29", printer=""):
        try:
            size = TAG_SIZES.get(size_key or "62x29", (62, 29))
            for it in items or []:
                img = render_tag({"name": it.get("name"), "programme": it.get("programme"), "nqf": it.get("nqf")},
                                 it.get("code") or "", it.get("event") or "Camblish Alumni Hub", size)
                print_image(img, printer or "")
            return {"ok": True}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def print_png(self, images_b64, printer=""):
        """Print ready-made tag images (rendered by the hub page) straight to the printer."""
        try:
            for b in images_b64 or []:
                img = Image.open(io.BytesIO(base64.b64decode(b))).convert("RGB")
                print_image(img, printer or "")
            return {"ok": True}
        except Exception as e:
            return {"ok": False, "error": str(e)}

    def send_email(self, to, subject, body):
        try:
            import win32com.client
            outlook = win32com.client.Dispatch("Outlook.Application")
            mail = outlook.CreateItem(0)
            mail.To = to
            mail.Subject = subject
            mail.Body = body
            mail.Send()
            return {"ok": True, "method": "outlook"}
        except Exception:
            pass
        try:
            url = "mailto:%s?subject=%s&body=%s" % (urllib.parse.quote(to), urllib.parse.quote(subject), urllib.parse.quote(body))
            os.startfile(url)
            return {"ok": True, "method": "mailto"}
        except Exception as e:
            return {"ok": False, "error": str(e)}


def centre_window(hwnd):
    """Open at a comfortable size in the middle of the screen. Maximise still fills the screen."""
    try:
        import ctypes
        from ctypes import wintypes
        user32 = ctypes.windll.user32
        user32.ShowWindow(hwnd, 9)                      # restore if Windows opened it maximised
        wa = wintypes.RECT()
        user32.SystemParametersInfoW(0x0030, 0, ctypes.byref(wa), 0)
        scale = (ctypes.windll.shcore.GetScaleFactorForDevice(0) or 100) / 100.0
        aw, ah = wa.right - wa.left, wa.bottom - wa.top
        w = int(min(aw * 0.8, 1320 * scale)); h = int(min(ah * 0.86, 860 * scale))
        x = wa.left + (aw - w) // 2; y = wa.top + (ah - h) // 2
        user32.SetWindowPos(hwnd, 0, x, y, w, h, 0x0004 | 0x0040)   # no z-order change, show
    except Exception:
        pass


def set_window_icon(title):
    """Give the window and taskbar the Alumni Hub icon instead of the Python one."""
    try:
        import ctypes
        import time
        user32 = ctypes.windll.user32
        ico = resource("app.ico")
        for _ in range(60):
            hwnd = user32.FindWindowW(None, title)
            if hwnd:
                big = user32.LoadImageW(None, ico, 1, 256, 256, 0x10)
                small = user32.LoadImageW(None, ico, 1, 32, 32, 0x10)
                user32.SendMessageW(hwnd, 0x80, 1, big)
                user32.SendMessageW(hwnd, 0x80, 0, small)
                centre_window(hwnd)
                return
            time.sleep(0.25)
    except Exception:
        pass


def window_size():
    """A centred window about 80% of the usable screen, in the same units pywebview uses."""
    try:
        import ctypes
        from ctypes import wintypes
        r = wintypes.RECT()
        ctypes.windll.user32.SystemParametersInfoW(0x0030, 0, ctypes.byref(r), 0)   # work area, excludes taskbar
        scale = ctypes.windll.shcore.GetScaleFactorForDevice(0) / 100.0 or 1.0
        aw, ah = (r.right - r.left) / scale, (r.bottom - r.top) / scale
        return int(max(860, min(1320, aw * 0.8))), int(max(600, min(860, ah * 0.85)))
    except Exception:
        return 1200, 780


def main():
    try:
        import ctypes
        ctypes.windll.shcore.SetProcessDpiAwareness(1)
        ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID("Camblish.AlumniHub.1")
    except Exception:
        pass
    import threading
    threading.Thread(target=set_window_icon, args=(APP_TITLE,), daemon=True).start()
    storage = os.path.join(os.environ.get("APPDATA", os.path.expanduser("~")), "CamblishAlumniHub")
    os.makedirs(storage, exist_ok=True)
    url = resource("hub.html")
    try:
        import urllib.request
        urllib.request.urlopen(HUB_URL, timeout=5)
        url = HUB_URL          # always the latest version from GitHub
    except Exception:
        pass                   # offline: use the copy bundled with the app
    w, h = window_size()
    # Opens centred at a comfortable size; Maximise fills the screen and the edges can be dragged to any size.
    webview.create_window(APP_TITLE, url=url, js_api=Bridge(), width=w, height=h,
                          min_size=(860, 600), resizable=True, background_color="#081a45", text_select=True)
    webview.start(http_server=url != HUB_URL, private_mode=False, storage_path=storage)


if __name__ == "__main__":
    main()
